const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const str = buf.toString('utf8');
let idx = 0;
while (true) {
  idx = str.indexOf('CREATE TABLE', idx);
  if (idx === -1) break;
  // Print from CREATE TABLE to the next semicolon or 500 chars
  const end = str.indexOf(';', idx);
  const snippet = str.slice(idx, end !== -1 ? end+1 : idx+500);
  console.log(snippet);
  console.log('---');
  idx += 12;
}
"

node -e "
const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const str = buf.toString('utf8');
// Find all CREATE TABLE statements
const re = /CREATE TABLE[^;]+/g;
let match;
const tables = [];
while ((match = re.exec(str)) !== null) {
  tables.push(match[0].split('\n').slice(0,2).join(' ').trim());
}
// Deduplicate
[...new Set(tables)].forEach(t => console.log(t));
"

node -e "
const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const str = buf.toString('utf8');
// Find all CREATE TABLE full statements
const re = /CREATE TABLE[^)]+\)/g;
let match;
const seen = new Set();
while ((match = re.exec(str)) !== null) {
  const tname = match[0].match(/CREATE TABLE \"?(\w+)/);
  if (tname && !seen.has(tname[1])) {
    seen.add(tname[1]);
    console.log(match[0] + '\n---');
  }
}
"

